import pico from './vendor/pico.mjs';
let classifier;
export function faceCrop(width,height,faces,ratio=.8){if(!faces.length)return null;const left=Math.max(0,Math.min(...faces.map(f=>f.x))),top=Math.max(0,Math.min(...faces.map(f=>f.y))),right=Math.min(width,Math.max(...faces.map(f=>f.x+f.width))),bottom=Math.min(height,Math.max(...faces.map(f=>f.y+f.height)));let w=Math.max((right-left)*1.9,(bottom-top)*2.5*ratio),h=w/ratio;if(w>width||h>height){const factor=Math.min(width/w,height/h);w*=factor;h*=factor}if(w<(right-left)*1.15||h<(bottom-top)*1.25)return null;const x=Math.max(0,Math.min(width-w,(left+right)/2-w/2)),y=Math.max(0,Math.min(height-h,top-(h-(bottom-top))*.32));if(left<x||right>x+w||top<y||bottom>y+h)return null;return{x,y,width:w,height:h}}
async function detect(image){const canvas=document.createElement('canvas'),scale=Math.min(1,640/Math.max(image.width,image.height));canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0,canvas.width,canvas.height);if(typeof window.FaceDetector==='function'){try{const results=await new window.FaceDetector({fastMode:false,maxDetectedFaces:20}).detect(canvas);if(results.length)return results.map(f=>({x:f.boundingBox.x/scale,y:f.boundingBox.y/scale,width:f.boundingBox.width/scale,height:f.boundingBox.height/scale}))}catch{}}
 if(!classifier)classifier=fetch('/vendor/facefinder.bin').then(r=>{if(!r.ok)throw Error('Face model unavailable');return r.arrayBuffer()}).then(bytes=>pico.unpack_cascade(new Int8Array(bytes)));const classify=await classifier,data=ctx.getImageData(0,0,canvas.width,canvas.height).data,gray=new Uint8Array(canvas.width*canvas.height);for(let i=0;i<gray.length;i++)gray[i]=Math.round(.299*data[i*4]+.587*data[i*4+1]+.114*data[i*4+2]);const candidates=pico.run_cascade({pixels:gray,nrows:canvas.height,ncols:canvas.width,ldim:canvas.width},classify,{shiftfactor:.1,minsize:Math.max(28,Math.min(canvas.width,canvas.height)/12),maxsize:Math.min(canvas.width,canvas.height),scalefactor:1.15});return pico.cluster_detections(candidates,.2).filter(f=>f[3]>5).slice(0,20).map(f=>({x:(f[1]-f[2]/2)/scale,y:(f[0]-f[2]/2)/scale,width:f[2]/scale,height:f[2]/scale}))}
export async function prepareNewsPhoto(file,{smart=true,limit=409600}={}){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>20*1024*1024)throw Error('اختر صورة JPEG أو PNG أو WebP أقل من 20 ميجابايت.');const image=await createImageBitmap(file);try{let faces=[];if(smart)try{faces=await detect(image)}catch{}const crop=smart?faceCrop(image.width,image.height,faces):null,canvas=document.createElement('canvas');for(let attempt=0;attempt<7;attempt++){const scale=.8**attempt;canvas.width=Math.round(1080*scale);canvas.height=Math.round(1350*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);if(crop)ctx.drawImage(image,crop.x,crop.y,crop.width,crop.height,0,0,canvas.width,canvas.height);else{const fit=Math.min(canvas.width/image.width,canvas.height/image.height);ctx.drawImage(image,(canvas.width-image.width*fit)/2,(canvas.height-image.height*fit)/2,image.width*fit,image.height*fit)}const blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',Math.max(.45,.8-attempt*.05)));if(blob&&blob.size<=limit)return{blob,cropped:!!crop,faces:faces.length}}throw Error('تعذر ضغط الصورة؛ اختر صورة أخرى.')}finally{image.close()}}
export function photoPicker({element:E,button:B,busy,onChange=()=>{}}){const box=E('fieldset'),input=E('input'),toggle=E('input'),label=E('label','القص الذكي حول الوجه','inline'),preview=E('div'),status=E('p');input.type='file';input.accept='image/jpeg,image/png,image/webp';input.multiple=true;toggle.type='checkbox';toggle.checked=true;label.prepend(toggle);box.append(E('legend','صور الخبر · حتى ٥ صور'),input,label,E('p','ألغِ التفعيل لإبقاء الصورة كاملة. المعاينة توضح القص قبل إرسال الطلب؛ يتم اكتشاف الوجه داخل جهازك.','muted'),status,preview);let files=[],photos=[],urls=[],generation=0,processing=false;async function paint(){processing=true;const n=++generation;status.textContent='تجهيز ومعاينة الصور…';input.disabled=toggle.disabled=true;try{const prepared=[];for(const file of files)prepared.push(await prepareNewsPhoto(file,{smart:toggle.checked}));if(n!==generation)return;photos=prepared;for(const url of urls)URL.revokeObjectURL(url);urls=[];preview.replaceChildren();for(const[p,idx]of prepared.map((p,i)=>[p,i])){const row=E('div'),img=E('img'),url=URL.createObjectURL(p.blob);urls.push(url);img.src=url;img.alt='الصورة '+(idx+1);img.className='request-photo-preview';row.append(img,E('small',p.cropped?'تم القص حول الوجه':'الصورة كاملة'),B('إزالة',()=>{files.splice(idx,1);return busy(null,paint)},'text-button danger'));preview.append(row)}status.textContent=photos.length+' / ٥ صور';onChange()}finally{if(n===generation){processing=false;input.disabled=toggle.disabled=false}}}
input.onchange=()=>busy(input,async()=>{const incoming=[...input.files];input.value='';if(files.length+incoming.length>5)throw Error('الحد الأقصى خمس صور.');if(incoming.some(f=>!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>20*1024*1024))throw Error('اختر صورًا صالحة أقل من 20 ميجابايت.');files.push(...incoming);await paint()});toggle.onchange=()=>busy(toggle,paint);return{element:box,get processing(){return processing},get photos(){return photos},get smart(){return toggle.checked},dispose(){generation++;for(const url of urls)URL.revokeObjectURL(url)},async upload(req,user){const paths=[];try{for(const p of photos){const path=user+'/'+crypto.randomUUID()+'.jpg';await req('/storage/v1/object/news-images/'+path,{method:'POST',body:p.blob,raw:true,headers:{'Content-Type':'image/jpeg'}});paths.push(path)}return paths}catch(e){if(paths.length)await req('/storage/v1/object/news-images',{method:'DELETE',body:{prefixes:paths}}).catch(()=>{});throw e}}}}
export async function requestPhotoViews(parent,paths,{req,element:E}){for(const path of paths||[]){const r=await req('/storage/v1/object/sign/news-images/'+path.split('/').map(encodeURIComponent).join('/'),{method:'POST',body:{expiresIn:600}});const img=E('img');img.alt='صورة الخبر المرفقة';img.className='request-photo-preview';img.src='https://dlkykiducjimwehfhxfq.supabase.co/storage/v1'+r.signedURL;parent.append(img)}}
